        }
        sort(top.begin(), top.end(), [](const Cand& a, const Cand& b){ return a.key < b.key; });

        int pick = 0;
        double temp = max(0.05, 2.0 * (1.0 - min(1.0, elapsed / max(0.001, deadlineSeconds))));
        if (top.size() > 1 && U(rng) < 0.20 * temp) {
